/bin/bash -c "python - <<'PY'
import numpy as np
z=np.load('source_pixels.npz')['rgb']
bg=np.median(z,axis=0).astype(np.uint8)
# print RGB values for f0 object pixels and bg at same spot, to see transparent compositing vs pasted opaque
for name,(x0,y0,x1,y1) in {'A':(14,58,48,88),'B':(88,56,112,88),'C':(160,58,180,88)}.items():
 print('\\n',name)
 for y in range(y0,y1,2):
  line=[]
  for x in range(x0,x1,2):
   d=np.abs(z[0,y,x].astype(int)-bg[y,x].astype(int)).max()
   if d>15:
    line.append(f'{x}:{tuple(z[0,y,x])}/{tuple(bg[y,x])}')
  if line: print(y,' '.join(line))
PY"
